    paths=list(HERE.glob('*.py'))+[ROOT/'stage/runs/t258_closed_loop_retention/summary.json',source/'summary.json',source/'updates.jsonl',source/'training.jsonl'];plan['input_hashes']={**old['input_hashes'],**{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}}
    used=sum(p.stat().st_size for p in (ROOT/'stage/runs').rglob('*') if p.is_file());assert used+plan['final_bytes']<plan['global_bytes'] and shutil.disk_usage(ROOT).free>plan['min_free_bytes']
